    // sum lambda = 1, lambda >= 0
    // Variables: lambda_0..lambda_{m-1}, t+ t- (t=t+-t-)
    int n=m+2;
    vector<vector<double>> A;
    vector<double> b,c(n,0);
    c[m]=1; c[m+1]=-1;
